/* CSS PART 2 OF 2 */

/* Contact and conversion area */
.contact-section {
  padding-block: var(--space-2xl);
  background: var(--color-paper);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 8vw, 105px);
}

.contact-copy h2 {
  margin-bottom: 24px;
}

.contact-copy > p {
  max-width: 430px;
}

.contact-note {
  margin-top: 35px;
  padding: 22px 24px;
  border-left: 4px solid var(--color-orange);
  background: var(--color-white);
  color: var(--color-ink-soft);
  font-size: 0.92rem;
}

.contact-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 21px;
  padding: clamp(24px, 4vw, 42px);
  background: var(--color-white);
  box-shadow: var(--shadow-soft);
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field.full-width {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--color-navy);
  font-size: 0.79rem;
  font-weight: 800;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 50px;
  padding: 12px 14px;
  border: 1px solid #c9cbc6;
  border-radius: var(--radius-sm);
  background: #fcfcfa;
  color: var(--color-ink);
  font-size: 0.92rem;
  transition: border-color 180ms ease;
}

.form-field textarea {
  min-height: 140px;
  resize: vertical;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--color-orange);
  outline: 2px solid transparent;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #777f80;
}

.form-submit {
  grid-column: 1 / -1;
  justify-self: start;
  min-width: 190px;
}

.form-disclaimer {
  grid-column: 1 / -1;
  margin: -8px 0 0;
  color: var(--color-ink-soft);
  font-size: 0.76rem;
}

/* Footer */
.site-footer {
  padding-block: 52px 24px;
  background: var(--color-navy);
  color: var(--color-white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 35px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
}

.footer-brand .brand-name {
  color: var(--color-white);
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, 0.68);
}

.footer-copy {
  max-width: 420px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.76);
  font-size: 0.9rem;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
}

.footer-bottom p {
  margin: 0;
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.75rem;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.78rem;
}

.footer-links a:hover {
  color: #ffb47f;
}

/* Accessible mobile navigation controls */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-sm);
  background: var(--color-white);
  color: var(--color-navy);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Intermediate screens */
@media (max-width: 1000px) {
  :root {
    --header-height: 76px;
    --space-2xl: 76px;
  }

  .header-inner {
    gap: 16px;
  }

  .primary-nav {
    gap: 16px;
  }

  .primary-nav a:not(.button) {
    font-size: 0.76rem;
  }

  .brand img {
    width: 56px;
    height: 56px;
  }

  .brand-name {
    font-size: 1.12rem;
  }

  .why-layout,
  .roofing-layout,
  .contact-layout {
    gap: 42px;
  }

  .projects-grid {
    grid-template-rows: 270px 270px;
  }
}

/* Tablet and mobile navigation */
@media (max-width: 760px) {
  :root {
    --gutter: 22px;
    --header-height: 72px;
    --space-2xl: 68px;
  }

  .header-inner {
    position: relative;
    min-height: var(--header-height);
  }

  .brand img {
    width: 49px;
    height: 49px;
  }

  .brand-name {
    font-size: 1.02rem;
  }

  .brand-description {
    font-size: 0.56rem;
  }

  .menu-toggle {
    display: flex;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: calc(100% + 1px);
    right: -11px;
    left: -11px;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 12px 22px 20px;
    border-top: 1px solid var(--color-line);
    background: var(--color-white);
    box-shadow: var(--shadow-soft);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    padding: 13px 0;
    border-bottom: 1px solid var(--color-line);
    font-size: 0.88rem;
  }

  .primary-nav .header-cta {
    width: 100%;
    margin-top: 14px;
    white-space: normal;
  }

  .hero {
    min-height: 650px;
    min-height: min(720px, calc(100svh - var(--header-height)));
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(15, 32, 41, 0.91),
      rgba(15, 32, 41, 0.63)
    );
  }

  .hero-image {
    object-position: 60% center;
  }

  .hero-content {
    padding-block: 80px;
  }

  .hero h1 {
    font-size: clamp(3.2rem, 11vw, 5.3rem);
  }

  .trust-inner {
    grid-template-columns: 1fr;
    gap: 0;
    padding-block: 10px;
  }

  .trust-item,
  .trust-item:first-child {
    padding: 17px 0;
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.18);
  }

  .trust-item:last-child {
    border-bottom: 0;
  }

  .trust-value {
    font-size: 1.65rem;
  }

  .why-layout,
  .roofing-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 38px;
  }

  .why-copy {
    max-width: 620px;
  }

  .roofing-image-wrap {
    min-height: 430px;
  }

  .process-heading,
  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .process-heading .section-heading,
  .projects-heading .section-heading {
    margin-bottom: 20px;
  }

  .process-heading > p,
  .projects-heading > p {
    max-width: 540px;
    margin-bottom: 28px;
  }

  .process-list {
    grid-template-columns: 1fr 1fr;
