}

/* Narrow mobile screens */
@media (max-width: 480px) {
  :root {
    --gutter: 18px;
    --space-2xl: 56px;
  }

  body {
    font-size: 15px;
  }

  .container {
    width: calc(100% - var(--gutter) * 2);
  }

  .section-heading {
    margin-bottom: 30px;
  }

  .hero {
    min-height: 670px;
    min-height: min(760px, calc(100svh - var(--header-height)));
  }

  .hero-image {
    object-position: 64% center;
  }

  .hero::before {
    background: linear-gradient(
      90deg,
      rgba(15, 32, 41, 0.92) 0%,
      rgba(15, 32, 41, 0.76) 68%,
      rgba(15, 32, 41, 0.46) 100%
    );
  }

  .hero-content {
    padding-block: 66px;
  }

  .hero h1 {
    font-size: clamp(3rem, 13vw, 4.2rem);
  }

  .hero-description {
    font-size: 0.98rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    align-items: flex-start;
    font-size: 0.72rem;
  }

  .brand {
    gap: 9px;
  }

  .brand img {
    width: 43px;
    height: 43px;
  }

  .brand-name {
    font-size: 0.94rem;
  }

  .brand-description {
    max-width: 190px;
    font-size: 0.51rem;
  }

  .why-detail {
    grid-template-columns: 38px 1fr;
    gap: 13px;
  }

  .why-number {
    font-size: 1.5rem;
  }

  .roofing-image-wrap {
    min-height: 320px;
  }

  .roofing-signs {
    grid-template-columns: 1fr;
  }

  .process-list {
    grid-template-columns: 1fr;
  }

  .process-step,
  .process-step:not(:first-child),
  .process-step:nth-child(even) {
    padding: 22px 0;
    border-right: 0;
    border-bottom: 1px solid #c9c9c0;
  }

  .process-step:last-child {
    border-bottom: 0;
  }

  .process-index {
    margin-bottom: 17px;
    font-size: 2.3rem;
  }

  .projects-grid {
    grid-template-columns: 1fr;
    grid-template-rows: 310px 240px 240px;
  }

  .project-card:first-child {
    grid-column: auto;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 17px;
    padding: 21px 17px;
  }

  .form-field.full-width,
  .form-submit,
  .form-disclaimer {
    grid-column: 1;
  }

  .form-submit {
    width: 100%;
  }

  .footer-main {
    gap: 22px;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
  }

  .footer-links {
    gap: 14px 20px;
  }
}

/* Hover-capable devices only */
@media (hover: hover) and (pointer: fine) {
  .primary-nav a,
  .footer-links a,
  .text-link {
    transition: color 180ms ease;
  }

  .button:hover,
  .project-card:hover img {
    will-change: transform;
  }
}

/* Motion accessibility */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .button:hover,
  .project-card:hover img {
    transform: none;
  }
}
